@startuml

class School {
  + name : string
}

class Teacher {
  + firstName : string
  + lastName : string
  + email : string
}

class Student {
  + firstName : string
  + lastName : string
}

class TeachingAssignment {
  + hours : int
}

class Room {
  + name : string
}

class Classroom extends Room {
  + capacity : int
}

class Gym extends Room {
  + size : float
}

class ClassGroup {
  + name : string
}

School "1" -- "1" Teacher : principal
School "1" -- "1..3" Teacher : works at
Teacher "1" -- "*" TeachingAssignment : has
TeachingAssignment "*" -- "1" School

Student "*" -- "1" ClassGroup : belongs to
ClassGroup "1" -- "1" Classroom : assigned to
Classroom "1" -- "1" ClassGroup : assigned to

School "1" *-- "*" Room
School "1" *-- "*" Teacher
School "1" *-- "*" Student
School "1" *-- "*" ClassGroup

@enduml

